
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_pbe50_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_pbe50", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.215902268225779e+00, -2.174001902179154e+00, -2.115310526869085e+00, -2.034054427655361e+00, -1.923434537609732e+00, -1.776437256970726e+00, -1.587759452531461e+00, -1.357289368008767e+00, -1.094675461049398e+00, -8.204510457240271e-01, -5.546189078117141e-01, -3.924055250365263e-01, -3.469629453165124e-01, -2.824079810663020e-01, -2.010134608791909e-01, -1.250812155496341e-01, -6.687920338001443e-02, -2.476246884355369e-02, -5.405965528298268e-03, -6.081010744730078e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


